import AppKit

/// Reads only eligible new clipboard contents. Source identity remains an estimate.
public struct ClipboardCapture {
    public static let sensitiveTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword"
    ]
    public private(set) var changeCount: Int

    public init(changeCount: Int) { self.changeCount = changeCount }
    public mutating func reset(to changeCount: Int) { self.changeCount = changeCount }

    public mutating func read(
        from pasteboard: NSPasteboard, enabled: Bool, excludedApps: String,
        ownBundleID: String?, frontmostBundleID: () -> String?
    ) -> String? {
        guard enabled, pasteboard.changeCount != changeCount else { return nil }
        changeCount = pasteboard.changeCount
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.sensitiveTypes) else { return nil }
        let excluded = Set(excludedApps.split(whereSeparator: { $0.isWhitespace }).map(String.init))
        guard let source = frontmostBundleID(), source != ownBundleID,
              !excluded.contains(source) else { return nil }
        guard let text = pasteboard.string(forType: .string),
              !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
              text.utf8.count <= 1_000_000 else { return nil }
        // Recheck identity, generation and markers after reading. A rejected generation
        // is consumed, so switching apps cannot make excluded content eligible later.
        guard frontmostBundleID() == source, pasteboard.changeCount == changeCount,
              Set((pasteboard.types ?? []).map(\.rawValue)).isDisjoint(with: Self.sensitiveTypes)
        else { return nil }
        return text
    }
}
